return ['domain'=>'press-permit-core','plural-forms'=>'nplurals=3; plural=(n == 1) ? 0 : (n >= 2 && n <= 4) ? 1 : 2;','language'=>'sk_SK','project-id-version'=>'PublishPress Permissions Free 4.8.2','pot-creation-date'=>'2026-04-22T11:57:22+00:00','po-revision-date'=>'2026-05-26 19:59+0000','x-generator'=>'WP-CLI 2.12.0','messages'=>['PublishPress Permissions Free'=>'PublishPress Permissions Free','https://publishpress.com/presspermit'=>'https://publishpress.com/presspermit','PublishPress Permissions allows you to enable or deny access to posts, pages, categories, tags and more.'=>'PublishPress Permissions vám umožňuje povoliť alebo zamietnuť prístup k príspevkom, stránkam, kategóriám, značkám a ďalším.','PublishPress'=>'PublikáciaPress','https://publishpress.com/'=>'https://publishpress.com/','Edit Tag for All Post Types'=>'Upraviť značku pre všetky typy príspevkov','Edit Tag for Posts'=>'Upraviť značku pre príspevky','Advanced Custom Fields'=>'Pokročilé vlastné polia','Control front-end access to Field Groups with advanced permission management.'=>'Ovládajte prístup na prednej strane k poliam s pokročilým spravovaním oprávnení.','Control access to Field Groups'=>'Ovládajte prístup k skupinám polí','Front-end visibility restrictions'=>'Obmedzenia viditeľnosti na front-ende','Integration with permission groups'=>'Integrácia so skupinami povolení','Beaver Builder'=>'Beaver Builder','Compatibility with Edit Permissions in Beaver Builder.'=>'Kompatibilita s úpravou povolení v Beaver Builder.','Beaver editor integration'=>'Integrácia s editorom Beaver','Widget-level permission controls'=>'Ovládanie povolení na úrovni widgetu','Template access restrictions'=>'Obmedzenia prístupu k šablónam','bbPress Forums'=>'bbPress Fóra','Forum-specific permissions for bbPress with detailed control over forum access and participation.'=>'Oprávnenia špecifické pre fórum pre bbPress s podrobným ovládaním prístupu a účasti na fóre.','Forum-specific permissions'=>'Povolenia špecifické pre fórum','Topic creation restrictions'=>'Obmedzenia vytvárania tém','Forum access controls'=>'Ovládanie prístupu na fóre','BuddyPress'=>'BuddyPress','Assign post and term permissions to BuddyPress groups for enhanced content control.'=>'Priraďte oprávnenia príspevkov a výrazov k skupinám BuddyPress pre vylepšené riadenie obsahu.','Assign post permissions to BuddyPress groups'=>'Priradiť oprávnenia na príspevky skupinám BuddyPress','Assign term permissions to BuddyPress groups'=>'Priradiť oprávnenia na termíny skupinám BuddyPress','Group-based content permissions'=>'Oprávnenia na obsah na základe skupín','CMS Tree View'=>'CMS zobrazenie stromu','Compatibility with Edit Permissions in CMS Tree View.'=>'Kompatibilita s úpravou oprávnení v zobrazení stromu CMS.','Permission-aware tree view'=>'Zobrazenie stromu s vedomím o oprávneniach','Hierarchical content controls'=>'Hierarchické ovládanie obsahu','Elementor'=>'Elementor','Compatibility with Edit Permissions in Elementor.'=>'Kompatibilita s úpravou oprávnení v Elementore.','Elementor editor integration'=>'Integrácia editora Elementor','The Events Calendar'=>'Kalendár udalostí','Apply permission controls to events and event-related content.'=>'Použiť ovládanie oprávnení na udalosti a obsah súvisiaci s udalosťami.','Event post permissions'=>'Oprávnenia na príspevky udalostí','Event taxonomy controls'=>'Ovládanie taxonómie udalostí','Nested Pages'=>'Vnorene stránky','Compatibility with Edit Permissions in Nested Pages.'=>'Kompatibilita s úpravou oprávnení vo vnorenej stránke.','Permission-aware nested view'=>'Povolenia vedomý vnorený pohľad','Quick edit integration'=>'Rýchla integrácia úprav','PublishPress Statuses'=>'Stavy PublishPress','Compatibility with PublishPress Statuses plugin.'=>'Kompatibilita s pluginom PublishPress Statuses.','Custom status permissions'=>'Vlastné povolenia pre stavy','Workflow-specific access controls'=>'Prístupové kontroly špecifické pre pracovný tok','Status-based editing capabilities'=>'Možnosti úprav založené na stave','Relevanssi'=>'Relevanssi','Filter search results based on View Permissions for secure content discovery.'=>'Filtrovať výsledky vyhľadávania na základe oprávnení na zobrazenie pre bezpečné objavovanie obsahu.','Search result filtering'=>'Filtrovanie výsledkov vyhľadávania','Permission-aware indexing'=>'Povolenia vedomé indexovanie','Secure content discovery'=>'Bezpečné objavovanie obsahu','SearchWP'=>'SearchWP','Compatibility with SearchWP term filtering for advanced search capabilities.'=>'Kompatibilita s filtrovaním termínov SearchWP pre pokročilé vyhľadávacie možnosti.','Permission-aware search results'=>'Povolenia vedomé výsledky vyhľadávania','Term-based filtering'=>'Filtrovanie na základe termínov','Advanced search controls'=>'Pokročilé vyhľadávacie kontroly','WooCommerce'=>'WooCommerce','Apply permission controls to WooCommerce products and product categories.'=>'Použiť kontrolu povolení na produkty WooCommerce a kategórie produktov.','Product permissions'=>'Povolenia pre produkty','Product category controls'=>'Ovládanie kategórií produktov','WPML'=>'WPML','Multilingual support with permission synchronization across content translations.'=>'Podpora viacerých jazykov s synchronizáciou oprávnení naprieč prekladmi obsahu.','Permission synchronization across translations'=>'Synchronizácia oprávnení naprieč prekladmi','Language-specific content access'=>'Prístup k obsahu špecifickému pre jazyk','Multilingual permission management'=>'Viacjazyčné spravovanie oprávnení','Yoast SEO'=>'Yoast SEO','Exclude restricted posts from XML sitemaps to maintain proper SEO indexing.'=>'Vylúčenie obmedzených príspevkov z XML sitemaps na udržanie správneho SEO indexovania.','Sitemap filtering for restricted content'=>'Filtrovanie sitemaps pre obmedzený obsah','Search engine visibility controls'=>'Ovládanie viditeľnosti vo vyhľadávačoch','Permission-aware XML sitemaps'=>'XML sitemaps vedomé oprávnení','YooTheme'=>'YooTheme','Compatibility with YooTheme builder and term permissions.'=>'Kompatibilita s YooTheme builderom a oprávneniami termínov.','Builder interface compatibility'=>'Kompatibilita rozhrania buildera','Term permission integration'=>'Integrácia oprávnení termínov','Template access controls'=>'Ovládanie prístupu k šablónam','Viewing'=>'Zobrazenie','Access Circles'=>'Prístupové kruhy','Editing Permissions'=>'Úprava oprávnení','Compatibility Pack'=>'Kompatibilitný balík','Teaser'=>'Upútavka','File Access'=>'Prístup k súborom','Membership'=>'Členstvo','User Posts'=>'Príspevky používateľov','Visibility Circles and Editorial Circles block access to content not authored by other group members.'=>'Viditeľnostné kruhy a redakčné kruhy blokujú prístup k obsahu, ktorý nebol vytvorený inými členmi skupiny.','Post-specific and category-specific permissions for creation and editing.'=>'Právomoci špecifické pre príspevky a kategórie na vytváranie a úpravy.','Integration with ACF, bbPress, BuddyPress, Relevanssi, WPML and other plugins; enhanced Multisite support.'=>'Integrácia s ACF, bbPress, BuddyPress, Relevanssi, WPML a ďalšími pluginmi; vylepšená podpora pre Multisite.','On the site front end, display teaser text for unreadable posts instead of hiding them.'=>'Na prednej strane stránky zobrazte text náhľadu pre nečitateľné príspevky namiesto ich skrytia.','Restrict direct file requests based on user\'s access to the page a file is attached to.'=>'Obmedzte priame požiadavky na súbory na základe prístupu používateľa k stránke, ku ktorej je súbor pripojený.','Time-limit access customizations by delaying or expiring Permission Group membership.'=>'Omeďte prístupové prispôsobenia časovým obmedzením alebo expiráciou členstva v skupine oprávnení.','Auto-create a page for each user of specified roles. Compatible with several Team / Staff plugins.'=>'Automaticky vytvorte stránku pre každého používateľa so špecifikovanými rolami. Kompatibilné s niekoľkými pluginmi pre tím / zamestnancov.','Visibility Circles and Editorial Circles block access to content not authored by other group members. Any WP Role, BuddyPress Group or custom Group can be marked as a Circle for specified post types.'=>'Viditeľnostné kruhy a redakčné kruhy blokujú prístup k obsahu, ktorý nebol vytvorený inými členmi skupiny. Akákoľvek WP rola, skupina BuddyPress alebo vlastná skupina môžu byť označené ako kruh pre špecifikované typy príspevkov.','Supports content-specific permissions for editing, term assignment and page parent selection. In combination with other modules, supports workflow statuses, PublishPress and PublishPress Revisions.'=>'Podporuje oprávnenia špecifické pre obsah pre úpravy, priraďovanie výrazov a výber nadriadených stránok. V kombinácii s inými modulmi podporuje stavy pracovného postupu, PublishPress a PublishPress Revisions.','Adds compatibility or integration with ACF, bbPress, Relevanssi, CMS Tree Page View, Custom Post Type UI, Subscribe2, WPML, various other plugins. Configure any BuddyPress Group as a Permissions Group. For multisite, provides network-wide Permission Groups.'=>'Pridáva kompatibilitu alebo integráciu s ACF, bbPress, Relevanssi, CMS Tree Page View, Custom Post Type UI, Subscribe2, WPML a rôznymi ďalšími pluginmi. Konfigurujte akúkoľvek skupinu BuddyPress ako skupinu oprávnení. Pre multisite poskytuje skupiny oprávnení na úrovni siete.','On the site front end, replace non-readable content with placeholder text. Can be enabled for any post type. Custom filters are provided but no programming is required for basic usage.'=>'Na prednej strane stránky nahraďte nečitateľný obsah textom zástupcu. Môže byť povolené pre akýkoľvek typ príspevku. Poskytujú sa vlastné filtre, ale na základné použitie nie je potrebné programovanie.','Filters direct file access, based on user\'s access to post(s) which the file is attached to. No additional configuration required. Creates/modifies .htaccess file in uploads folder (and in main folder for multisite).'=>'Filtrovanie priameho prístupu k súborom na základe prístupu používateľa k príspevkom, ku ktorým je súbor pripojený. Nie je potrebná žiadna ďalšia konfigurácia. Vytvára/modifikuje .htaccess súbor v priečinku nahrávania (a v hlavnom priečinku pre multisite).','Allows Permission Group membership to be date-limited (delayed and/or scheduled for expiration). Simple date picker UI alongside group membership selection.'=>'Umožňuje obmedzenie členstva v skupine oprávnení podľa dátumu (odložené a/alebo naplánované na expiráciu). Jednoduché užívateľské rozhranie na výber dátumu spolu s výberom členstva v skupine.','Create or synchronize posts to match users. Designed for Team / Staff plugins, but with broad usage potential.'=>'Vytvorte alebo synchronizujte príspevky, aby zodpovedali používateľom. Navrhnuté pre pluginy tímu / zamestnancov, ale s širokým potenciálom použitia.','If you like %s, please leave us a %s rating. Thank you!'=>'Ak sa vám páči %s, prosím, zanechajte nám %s hodnotenie. Ďakujeme!','About PublishPress Permissions'=>'O PublishPress Permissions','About'=>'O aplikácii','Permissions Documentation'=>'Dokumentácia oprávnení','Documentation'=>'Dokumentácia','Contact the PublishPress team'=>'Kontaktujte tím PublishPress','Contact'=>'Kontakt','Permission Group'=>'Skupina oprávnení','Specific Permissions: restrictions (\'Blocked\') take priority over additions (\'Enabled\')'=>'Špecifické oprávnenia: obmedzenia (\'Blokované\') majú prednosť pred pridaním (\'Povolené\')','Specific Permissions: no restrictions (\'Blocked\') can be applied to custom-defined groups'=>'Špecifické oprávnenia: žiadne obmedzenia (\'Blokované\') sa nemôžu aplikovať na vlastne definované skupiny','Extra Roles assignment available for {All} and {Anonymous} metagroups'=>'Priradenie dodatočných rolí dostupné pre metaskupiny {All} a {Anonymous}','Allow the {All} and {Anonymous} metagroups to be granted specific reading permissions for private content'=>'Povoliť metaskupinám {All} a {Anonymous} pridelenie špecifických čítacích oprávnení pre súkromný obsah','Users who have specific editing permissions for a post or attachment can also delete it'=>'Používatelia, ktorí majú špecifické oprávnenia na úpravu príspevku alebo prílohy, môžu tiež tieto odstrániť','Users who have custom editing permissions for an attachment can also delete it'=>'Používatelia, ktorí majú vlastné oprávnenia na úpravu prílohy, môžu tiež túto odstrániť','Disable front end filtering if logged user is a content administrator (normally filter to force inclusion of readable private posts in get_pages() listing, post counts, etc.'=>'Deaktivovať filtrovanie na frontende, ak je prihlásený používateľ administrátorom obsahu (normálne filtrovať, aby sa zabezpečilo zahrnutie čitateľných súkromných príspevkov v zozname get_pages(), počty príspevkov atď.','Disable front end filtering for all users (subject to limitation by PP_UNFILTERED_FRONT_TYPES)'=>'Deaktivovať filtrovanie na frontende pre všetkých používateľov (s výnimkou obmedzenia podľa PP_UNFILTERED_FRONT_TYPES)','Comma-separated list of post types to limit the effect of PP_UNFILTERED_FRONT and apply_filters( \'presspermit_skip_cap_filtering\' )'=>'Zoznam typov príspevkov oddelený čiarkami, aby sa obmedzil účinok PP_UNFILTERED_FRONT a apply_filters( \'presspermit_skip_cap_filtering\' )','Specific Permissions: additions (\'Enabled\') are not applied, cannot be assigned'=>'Špecifické oprávnenia: pridania (\'Povolené\') sa neuplatňujú, nemôžu byť priradené','Don\'t assign or apply specific permissions for the \'post\' type'=>'Nerobte priradenie ani neuplatňujte špecifické oprávnenia pre typ \'príspevok\'','Don\'t assign or apply specific permissions for the \'page\' type'=>'Nerobte priradenie ani neuplatňujte špecifické oprávnenia pre typ \'stránka\'','Don\'t assign or apply specific permissions for the \'media\' type'=>'Nerobte priradenie ani neuplatňujte špecifické oprávnenia pre typ \'mediatyp\'','Don\'t assign or apply specific permissions for the specified custom post type'=>'Neradiť ani neuplatňovať špecifické oprávnenia pre zadaný vlastný typ príspevku','Include scheduled posts in the posts query if user can edit them'=>'Zahrnúť naplánované príspevky do dotazu príspevkov, ak ich môže používateľ upravovať','Don\'t filter term post counts in get_terms() call'=>'Nefiltrovať počty príspevkov v get_terms() volaní','Leave unreadable posts on WP Navigation Menus'=>'Nechať nečitateľné príspevky na navigačných menu WP','Don\'t apply CSS to hide empty Nav Menus'=>'Nenaťahovať CSS na skrytie prázdnych navigačných menu','For legacy Nav Menus, hide empty nav menu div'=>'Pre staršie navigačné menu skryť prázdny div navigačného menu','Leave terms with no readable posts on WP Navigation Menus'=>'Nechať termíny bez čitateľných príspevkov na navigačných menu WP','When Teaser is applied with Redirect enabled, append original url as redirect_to argument'=>'Keď je aplikovaný Teaser s povoleným presmerovaním, pridať pôvodnú URL ako argument redirect_to','For Teaser compatibility, specify a redirect argument to use instead of redirect_to'=>'Pre kompatibilitu s Teaserom, zadajte argument presmerovania na použitie namiesto redirect_to','For Teaser compatibility, specify an additional redirect argument other than redirect_to'=>'Pre kompatibilitu s Teaserom, zadajte dodatočný argument presmerovania iný ako redirect_to','For Teaser compatibility, prevent the pp_permissions argument from being appended to redirects'=>'Pre kompatibilitu s Teaserom, zabráňte pripojeniu argumentu pp_permissions k presmerovaniam','Filter priority for \'get_pages\' filter (default: 1)'=>'Priorita filtra pre filter \'get_pages\' (predvolené: 1)','Don\'t include readable private pages in the Pages widget or other wp_list_pages() / get_pages() results    '=>'Nezahŕňať čitateľné súkromné stránky vo widgete Strany alebo v iných výsledkoch wp_list_pages() / get_pages()    ','If some pages have been suppressed from get_pages() results, change child pages\' corresponding post_parent values to a visible ancestor'=>'Ak boli niektoré stránky potlačené vo výsledkoch get_pages(), zmeňte zodpovedajúce hodnoty post_parent pre podstránky na viditeľného predka','Never modify the post_parent value in the get_pages() result set, even if some pages have been suppressed'=>'Nikdy nemodifikujte hodnotu post_parent v súbore výsledkov get_pages(), aj keď boli niektoré stránky potlačené','For performance, change the get_pages() database query to return only a subset of fields, excluding post_content'=>'Pre výkon zmeňte databázový dotaz get_pages() tak, aby vracal len podmnožinu polí, s výnimkou post_content','Don\'t apply content teaser to get_pages() results (leave unreadable posts hidden)'=>'Neradiť obsahový teaser na výsledky get_pages() (nechať nečitateľné príspevky skryté)','If some terms have been suppressed from get_terms() results, change child terms\' corresponding parent values to a visible ancestor'=>'Ak boli niektoré termíny potlačené vo výsledkoch get_terms(), zmeňte zodpovedajúce hodnoty rodiča pre podtermíny na viditeľného predka','Never modify the parent value in the get_terms() result set, even if some terms have been suppressed'=>'Nikdy nemodifikujte hodnotu rodiča v súbore výsledkov get_terms(), aj keď boli niektoré termíny potlačené','Set Author to current user if autoset_post_author / autoset_page_author capability is assigned'=>'Nastaviť autora na aktuálneho používateľa, ak je priradená schopnosť autoset_post_author / autoset_page_author','Leave Media Library with normal access criteria based on user\'s role capabilities '=>'Nechať knižnicu médií s normálnymi prístupovými kritériami na základe schopností úlohy používateľa ','Accommodate front end uploading solutions that require page editing capabilities for the async upload request'=>'Prispôsobiť riešenia pre nahrávanie na frontende, ktoré vyžadujú schopnosti úpravy stránok pre asynchrónne požiadavky na nahrávanie','Treat media attached to unregistered post types as unattached, to avoid improper and confusing filtering'=>'Zaobchádzať s médiami pripojenými k nezaregistrovaným typom príspevkov ako s nepripojenými, aby sa predišlo nesprávnemu a mätúcemu filtrovanie','Attached Files Private setting available'=>'Nastavenie súkromných pripojených súborov je k dispozícii','Comma-separated list of mime types to exclude from File Access filtering'=>'Zoznam mime typov oddelených čiarkou, ktoré sa majú vylúčiť z filtrovania prístupu k súborom','Comma-separated list of mime types to include in File Access filtering (bypassing others)'=>'Zoznam mime typov oddelených čiarkami, ktoré sa majú zahrnúť do filtrovania prístupu k súborom (obchádzanie ostatných)','When file access is blocked, do not set the WP_Query 404 / 403 property'=>'Keď je prístup k súboru zablokovaný, nenastavujte vlastnosť WP_Query 404 / 403','HTTP status code to send when file access is blocked'=>'HTTP stavový kód, ktorý sa má poslať, keď je prístup k súboru zablokovaný','On Users listing, Permission groups in custom column are list filter links instead of group edit links'=>'Na zozname používateľov sú povolenia v vlastnom stĺpci odkazy na filtre zoznamu namiesto odkazov na úpravu skupín','Unlock Permissions > Settings > Core > Admin Back End > \'Hide non-editable posts\''=>'Odomknúť povolenia > Nastavenia > Základné > Admin Back End > \'Skryť needitable príspevky\'','Within the async-upload.php script, filter author\'s retrieval of the attachment they just uploaded'=>'V rámci skriptu async-upload.php filtrovať získavanie autora pripojenia, ktoré práve nahrali','Don\'t filter comment display or moderation within wp-admin'=>'Nefiltrovať zobrazenie komentárov alebo moderáciu v wp-admin','Allow Administrators to be added to Permission Groups, even though they are not restricted'=>'Povoliť administrátorom byť pridaní do povolení, aj keď nie sú obmedzení','If propagating permissions are assigned to a page branch, overwrite any explicitly assigned permissions in sub-pages'=>'Ak sú priradené dedičné povolenia k pobočke stránky, prepísať akékoľvek explicitne priradené povolenia v podstránkach','Max number of specific permissions to insert in a single database query (default 1000)'=>'Maximálny počet špecifických povolení na vloženie v jednom databázovom dotaze (predvolené 1000)','Don\'t tweak the admin menu indexes to position Permissions menu under Users'=>'Nemenejte indexy administrátorského menu na umiestnenie menu Povolenia pod Používateľmi','Don\'t add a Permissions menu. Instead, add menu items to the Users and Settings menus.'=>'Nehodiť menu povolení. Namiesto toho pridať položky menu do menu používateľov a nastavení.','Customize Permissions screen title for Groups'=>'Prispôsobte názov obrazovky Povolenia pre Skupiny','Customize Permission Groups caption on user profile'=>'Prispôsobte popis Povolení skupín na profile používateľa','Only one group is selectable on Add User screen'=>'Na obrazovke Pridať používateľa je možné vybrať iba jednu skupinu','Only one group is selectable on Edit User screen'=>'Na obrazovke Upraviť používateľa je možné vybrať iba jednu skupinu','Display a custom hint on Permissions > User Groups'=>'Zobraziť vlastný tip na Povolenia > Skupiny používateľov','Max number of non-hierarchical posts / terms to display at one time (per page)'=>'Maximálny počet nehierarchických príspevkov / termínov na zobrazenie naraz (na stránku)','Max number of hierarchical posts / terms to display at one time (per page)'=>'Maximálny počet hierarchických príspevkov / termínov, ktoré sa majú zobraziť naraz (na stránku)','Disable auto-determination of how many levels of page tree to make visble by default. Instead, use specified value.'=>'Deaktivovať automatické určovanie toho, koľko úrovní stromu stránky má byť predvolene viditeľných. Namiesto toho použiť špecifikovanú hodnotu.','Target number of visible pages/terms, used for auto-determination of number of visible levels'=>'Cieľový počet viditeľných stránok/termínov, používaný na automatické určenie počtu viditeľných úrovní','Make search function on the post selection metabox look at post content'=>'Urobiť funkciu vyhľadávania v metaboxe výberu príspevkov, aby sa pozerala na obsah príspevku','Make search function on the post selection metabox look at post excerpt'=>'Urobiť funkciu vyhľadávania v metaboxe výberu príspevkov, aby sa pozerala na úryvok príspevku','Search by last name instead of display name'=>'Hľadať podľa priezviska namiesto zobrazeného mena','User field to search by default'=>'Používateľské pole, podľa ktorého sa má hľadať predvolene','User meta fields selectable for search (comma-separated)'=>'Vyberateľné používateľské meta polia na vyhľadávanie (oddelené čiarkou)','User meta fields which should be treated as numeric (comma-separated)'=>'Používateľské meta polia, ktoré by sa mali považovať za číselné (oddelené čiarkou)','User meta fields which should be treated as boolean (comma-separated)'=>'Používateľské meta polia, ktoré by sa mali považovať za boolean (oddelené čiarkou)','Use display name for search results instead of user_login'=>'Použiť zobrazené meno pre výsledky vyhľadávania namiesto user_login','When synchronizing role metagroups to currently defined WP roles, don\'t delete groups for previously defined WP roles.'=>'Pri synchronizácii metaskupín úloh s aktuálne definovanými úlohami WP, nezmazať skupiny pre predtým definované úlohy WP.','Force detection of WP user roles which are appended dynamically but not stored to the WP database.'=>'Nútiť detekciu úloh používateľov WP, ktoré sú dynamicky pripojené, ale nie sú uložené v databáze WP.','To save memory on front end access, don\'t register any filters related to content editing'=>'Aby sa ušetrila pamäť pri prístupe na frontende, nezaregistrovať žiadne filtre týkajúce sa úpravy obsahu','Attached media do not have any comments, so don\'t append clauses to comment queries for them'=>'Pripojené médiá nemajú žiadne komentáre, takže nepridávať klauzuly do dotazov na komentáre pre ne','Reduce overhead of pages query (in get_pages() and wp-admin) by defaulting fields to a set list that does not include post_content '=>'Znížiť režijné náklady dotazu na stránky (v get_pages() a wp-admin) predvolením polí na stanovený zoznam, ktorý nezahŕňa post_content ','Reduce overhead of wp-admin posts query by defaulting fields to a set list that does not include post_content '=>'Znížte režijné náklady dopytu príspevkov wp-admin predvolením polí na stanovený zoznam, ktorý nezahŕňa post_content ','Reduce overhead of wp-admin Media query by defaulting fields to a set list that does not include post_content '=>'Znížte režijné náklady dopytu médií wp-admin predvolením polí na stanovený zoznam, ktorý nezahŕňa post_content ','Reduce overhead of wp-admin query for specified custom post type by defaulting fields to a set list that does not include post_content '=>'Znížte režijné náklady dopytu wp-admin pre špecifikovaný vlastný typ príspevku predvolením polí na stanovený zoznam, ktorý nezahŕňa post_content ','Work around database setup warnings (at plugin activation) on some servers'=>'Obídenie varovaní nastavenia databázy (pri aktivácii pluginu) na niektorých serveroch','Development use only (suppresses post_status = \'publish\' clause for unfiltered post types with anonymous user)'=>'Iba na vývojové použitie (potláča klauzulu post_status = \'publish\' pre nefiltrované typy príspevkov s anonymným používateľom)','Development use only (on front end, do not replace \'post_status = \'publish\'\' clause with filtered equivalent)'=>'Iba na vývojové použitie (na prednej strane, nenahradzujte klauzulu \'post_status = \'publish\'\' filtrami ekvivalentom)','Logged In'=>'Prihlásený','Not Logged In'=>'Nepřihlásený','Everyone'=>'Každý','Change Request Notifications'=>'Oznámenia o zmenách požiadaviek','Submitted Revision Editors'=>'Predložená revízia','Scheduled Change Notifications'=>'Naplánované oznámenia o zmenách','Scheduled Revision Monitors'=>'Naplánované revízne monitorovanie','Authenticated site users, except for Administrators'=>'Autentifikovaní používatelia stránky, okrem administrátorov','Anonymous users (not logged in)'=>'Anonymní používatelia (neprihlásení)','All users (including anonymous)'=>'Všetci používatelia (vrátane anonymných)','All users with the WordPress role of %s'=>'Všetci používatelia s rolou WordPress %s','%1$s %2$s'=>'%1$s %2$s','%1$s won&#39;t work until you upgrade PHP to version %2$s or later. Current version: %3$s'=>'%1$s nebude fungovať, kým neaktualizujete PHP na verziu %2$s alebo novšiu. Aktuálna verzia: %3$s','%1$s won&#39;t work until you upgrade %2$s to version %3$s or later.'=>'%1$s nebude fungovať, kým neaktualizujete %2$s na verziu %3$s alebo novšiu.','%1$s won&#39;t work until you upgrade WordPress to version %2$s or later.'=>'%1$s nebude fungovať, kým neaktualizujete WordPress na verziu %2$s alebo novšiu.','This version of %1$s cannot work with your current %2$s version. Please upgrade it to %3$s or later.'=>'Táto verzia %1$s nemôže pracovať s vašou aktuálnou verziou %2$s. Prosím, aktualizujte ju na %3$s alebo novšiu.','Duplicate %1$s module activated (%2$s in folder %3$s).'=>'Duplikovaný modul %1$s aktivovaný (%2$s v priečinku %3$s).','Dismiss'=>'Zavrieť','Custom Group'=>'Vlastná skupina','Custom Groups'=>'Vlastné skupiny','Groups'=>'Skupiny','(using default capabilities due to invalid %s definition)'=>'(používajú sa predvolené schopnosti kvôli neplatnej definícii %s)','%1$s&nbsp;%2$s&nbsp;%3$s-&nbsp;%4$s%5$s%6$s'=>'%1$s&nbsp;%2$s&nbsp;%3$s-&nbsp;%4$s%5$s%6$s','%1$s&nbsp;%2$s%3$s'=>'%1$s&nbsp;%2$s%3$s','Your license key has expired. For updates to PublishPress Permissions Pro and priority support, %splease renew%s.'=>'Vaša licenčná kľúčová platnosť vypršala. Pre aktualizácie PublishPress Permissions Pro a prioritnú podporu, %sprosím obnovte%s.','[WP %s]'=>'[WP %s]','All users with a WordPress %s role'=>'Všetci používatelia s rolou WordPress %s','All users who are logged in and have a role on the site'=>'Všetci používatelia, ktorí sú 